    static void main(Args _args)
    {
        METPickupAdviceController controller;

        controller = new METPickupAdviceController();
        controller.parmReportName(ssrsReportStr(METPickupAdvice, Liquor));
        controller.parmDialogCaption("@MET:PickAdvise");
        controller.parmArgs(_args);

        METPickupAdviceContract contract = controller.parmReportContract().parmRdpContract();

        if(_args.dataset() == tableNum(SalesTable))
        {
            SalesTable salesTable = _args.record();
            if(salesTable)
            {
                contract.parmSalesID(salesTable.SalesId);
            }
        }

        controller.startOperation();
    }
